requests.query:
query GetApplicationsCapability {
  applicationsCapability {
    ...ApplicationsCapabilityFields
    __typename
  }
}

fragment ApplicationsCapabilityFields on ApplicationsCapability {
  enabled
  scope
  settingKey
  source
  __typename
}

query GetServerSettings {
  getServerSettings {
    __typename
    key
    value
    description
    isEditable
    isDeletable
  }
  getEffectiveStreamingContentFlushIntervalMs
}

query GetAllWorkspaces {
  workspaces {
    __typename
    workspaceId
    name
    displayName
    config
    workspaceRootPath
    absolutePath
    kind
    isTemp
  }
}

query ListCollaborationRootHistory {
  listCollaborationRootHistory {
    __typename
    ... on AgentOrgRootHistoryObject {
      root_subject_kind
      root_run_id
      created_at
      archived_at
      is_active
      summary
      org
      closed_task_executions
      __typename
    }
    ... on AgentTeamRootHistoryObject {
      root_subject_kind
      root_run_id
      __typename
    }
  }
}

