query GetAgentRunResumeConfig($runId: String!) {
  getAgentRunResumeConfig(runId: $runId) {
    runId
    isActive
    metadataConfig {
      agentDefinitionId
      workspaceRootPath
      llmModelIdentifier
      llmConfig
      autoExecuteTools
      runtimeKind
      runtimeReference {
        runtimeKind
        sessionId
        threadId
        metadata
        __typename
      }
      __typename
    }
    modelConfigEditability {
      editable
      reason
      __typename
    }
    __typename
  }
}

query GetTaskWorkerTasks($agentRunIds: [String!]!, $teamRunIds: [String!]!) {
  taskWorkerTasks(agentRunIds: $agentRunIds, teamRunIds: $teamRunIds) {
    workerKind
    workerRunId
    task {
      taskId
      projectId
      description
      status
      __typename
